function titleSigil(t){
 const shapes={
 wanderer:'<ellipse cx="32" cy="32" rx="26" ry="11" transform="rotate(-35 32 32)"/><path d="M32 11L37 26L52 32L37 38L32 53L27 38L12 32L27 26Z"/>',
 vanguard:'<path d="M32 6L53 15V33L44 48L32 58L20 48L11 33V15Z"/><path d="M20 35L32 21L44 35M20 45L32 31L44 45"/>',
 neon:'<path d="M9 19H23L36 6M55 45H41L28 58M20 44L44 20M12 32L32 12L52 32L32 52Z"/><circle cx="32" cy="32" r="5"/>',
 void:'<circle cx="32" cy="32" r="23"/><path d="M40 10C17 11 13 45 36 55M7 43L57 21M51 9L54 13L59 14L54 17L52 22L49 17L45 15L49 13Z"/>',
 guardian:'<path d="M14 49L8 35L11 18M50 49L56 35L53 18M11 29L4 24M12 40L4 37M53 29L60 24M52 40L60 37M20 52L32 58L44 52M32 7L38 24L54 27L41 38L44 54L32 46L20 54L23 38L10 27L26 24Z"/>'
 };
 const ranked='<path d="M32 6L53 18V40L32 58L11 40V18Z"/><path d="M21 35L32 23L43 35M21 44L32 32L43 44"/>'+(t.threshold===1?'<path d="M20 15L17 5L27 10L32 2L37 10L47 5L44 15Z"/>':t.threshold===3?'<path d="M3 24V41M61 24V41"/>':'');
 return '<svg class="title-sigil" viewBox="0 0 64 64" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">'+(shapes[t.id]||ranked)+'</svg>';
}
function titleBadge(id){const t=titleCatalog.find(t=>t.id===id);return t?'<span class="equipped-title difficulty-'+(t.difficulty??'purchase')+'" style="--title-color:'+t.color+'">'+titleSigil(t)+'<span>'+t.name+'</span>'+(t.threshold?'<small>'+['N','H','EX'][t.difficulty]+' · '+t.threshold+'</small>':'')+'</span>':''}
let titleClaimSummary='',titleDifficulty=0;
function renderTitleCollection(){
 const owned=accountProfile?.titles?.owned||[],eligible=accountProfile?.titles?.eligible||[],equipped=accountProfile?.titles?.equipped,current=titleCatalog.find(t=>t.id===equipped),rank=accountProfile?.rank??0;
 $('storeBalance').textContent=save.gold.toLocaleString()+' G';
 const card=t=>{const has=owned.includes(t.id)||eligible.includes(t.id),on=equipped===t.id,locked=!accountReady||accountBusy||!!pendingOperation||!!accountProfile?.active;return '<article class="callsign-card difficulty-'+(t.difficulty??'purchase')+' '+(on?'is-equipped ':has?'is-owned ':'')+(t.threshold?'honor-tier-'+t.threshold:'honor-purchased')+'" style="--title-color:'+t.color+'"><div class="callsign-topline"><small>'+t.tag+'</small><span>'+(on?'장착 중':has?(t.price?'보유 중':'현재 사용 가능'):t.price?'골드 구매':'랭킹 보상')+'</span></div><div class="callsign-art"><div class="medal-halo"></div><div class="honor-emblem">'+titleSigil(t)+'<img src="assets/shaded_medal'+t.medal+'.png" alt="" loading="lazy"></div><span class="honor-grade">'+(t.threshold?'TOP '+String(t.threshold).padStart(2,'0'):'SECTOR / 09')+'</span></div><div class="callsign-name">'+t.name+'</div><p>'+t.desc+'</p><div class="callsign-bottom">'+(has?'<button data-title-equip="'+t.id+'" '+(on||locked?'disabled':'')+'>'+(on?'✓ 적용 중':'이 칭호 장착')+'</button>':t.price?'<button data-title-buy="'+t.id+'" '+(locked||save.gold<t.price?'disabled':'')+'><span>◆ '+t.price.toLocaleString()+' G</span><span>구매 + 장착 ↗</span></button>':'<span class="title-unlock-condition">전체 랭킹 '+(t.threshold===1?'1위':'TOP '+t.threshold)+' · 순위 유지 중 사용</span>')+'</div></article>'};
 $('storeItems').innerHTML='<div class="callsign-hero"><div><span class="eyebrow">YOUR CALLSIGN</span><h2>칭호 보관함</h2><p>구매 칭호와 현재 랭킹 칭호를 확인하고 장착하세요.</p><div class="callsign-preview"><span class="rank-badge rank-'+rank+'">'+ranksV3[rank]+'</span><b>'+escapeHTML(accountProfile?.nickname||'원정대원')+'</b>'+titleBadge(equipped)+'</div><small>'+(current?'현재 칭호 · '+current.name:'장착한 추가 칭호가 없습니다.')+'</small></div><div class="callsign-collection"><strong>'+owned.length+'<small> / '+titleCatalog.filter(t=>t.price).length+'</small></strong><span>영구 구매 칭호</span><button id="clearTitle" '+(!equipped||!accountReady||accountBusy?'disabled':'')+'>칭호 해제</button></div></div><div class="collection-heading"><div><span class="eyebrow">GOLD COLLECTION</span><h2>영구 소장 칭호</h2></div><span>영구 소장 · 능력치 영향 없음</span></div><div class="callsign-grid">'+titleCatalog.filter(t=>t.price).map(card).join('')+'</div><div class="collection-heading"><div><span class="eyebrow">HALL OF HONOR</span><h2>현재 랭킹 명예</h2></div><button id="claimTitles">↻ 현재 순위 확인</button></div><p class="title-section-note">각 난이도의 맵별 <b>전체 랭킹</b> 기준입니다. 해당 순위를 유지하는 동안만 사용할 수 있으며, 조건을 벗어나면 표시와 장착 권한이 해제됩니다. 화면에서 30초마다 갱신합니다. 구매 칭호는 영구 보유합니다.</p><p id="titleClaimStatus" role="status">'+titleClaimSummary+'</p><div class="title-mode-tabs" role="group" aria-label="랭킹 칭호 난이도">'+['NORMAL','HARD','EXTREME'].map((m,i)=>'<button data-title-mode="'+i+'" aria-pressed="'+(i===titleDifficulty)+'" class="difficulty-'+i+'">'+m+'<small>'+['전선의 명예','강철의 명예','극한의 명예'][i]+'</small></button>').join('')+'</div><p class="live-title-standing">'+['노멀','하드','익스트림'][titleDifficulty]+' 현재 최고 순위: '+(accountProfile?.titles?.best?.[titleDifficulty]?'#'+accountProfile.titles.best[titleDifficulty]:'등록 기록 없음')+' · 일시 사용 칭호</p><div class="callsign-grid ranking-titles">'+titleCatalog.filter(t=>t.threshold&&t.difficulty===titleDifficulty).map(card).join('')+'</div><section class="campaign-honors"><div class="collection-heading"><div><span class="eyebrow">CAMPAIGN HONORS</span><h2>계급의 기록</h2></div><span>추가 칭호와 함께 자동 표시</span></div><div class="store-title-grid">'+ranksV3.map((name,i)=>'<article class="campaign-rank rank-family-'+i+' '+(rank===i?'current':'')+'"><div class="rank-insignia"><img src="assets/title-rank-'+i+'.png" alt=""></div><div><b class="rank-'+i+'">'+['병사','부사관','사관','장군'][i]+'</b><span class="campaign-rank-name">'+name+'</span><p>'+['최초 시작','노멀 10단계 완주','하드 10단계 완주','익스트림 10단계 완주'][i]+'</p><small>'+(accountReady?(rank===i?'현재 계급':rank>i?'달성 완료':'미달성'):'기록 확인 중')+'</small></div></article>').join('')+'</div></section><p class="title-credits">메달·계급장: <a href="https://kenney.nl/assets/medals" target="_blank" rel="noopener">Kenney Medals</a> · <a href="https://kenney.nl/assets/ranks-pack" target="_blank" rel="noopener">Ranks Pack</a> / CC0</p>';
 $('storeItems').querySelectorAll('[data-title-buy]').forEach(b=>b.onclick=async()=>{const r=await transact('buy',{category:'title',item:b.dataset.titleBuy});if(r){rankingCache.clear();renderStore();renderCamp();toast('칭호 구매 · 장착 완료')}});
 $('storeItems').querySelectorAll('[data-title-equip]').forEach(b=>b.onclick=()=>equipTitle(b.dataset.titleEquip));$('clearTitle').onclick=()=>equipTitle(null);$('claimTitles').onclick=()=>claimRankingTitles();$('storeItems').querySelectorAll('[data-title-mode]').forEach(b=>b.onclick=()=>{titleDifficulty=+b.dataset.titleMode;renderStore()});
}
async function equipTitle(item){const r=await transact('equipTitle',{item});if(r){rankingCache.clear();renderStore();renderCamp();toast(item?'칭호를 장착했습니다.':'추가 칭호를 해제했습니다.')}}
async function claimRankingTitles(notify=true){const r=await transact('claimTitles');if(!r)return;titleClaimSummary='현재 순위 기준으로 사용 가능한 칭호 '+r.result.eligible.length+'종 · 순위 변경 시 자동 해제';if(view==='store')renderStore();renderCamp();if(notify)toast(titleClaimSummary);return r}
let titleRefreshing=false;
async function refreshLiveTitles(){if(titleRefreshing||!accountReady||accountBusy||pendingOperation||document.hidden||!(view==='camp'||(view==='store'&&storeSection==='titles')||$('rankModal').open))return;titleRefreshing=true;try{const r=await accountFetch('titles',{});applyProfile(r.profile);if(view==='store'&&storeSection==='titles')renderStore();if(view==='camp')renderCamp();if($('rankModal').open&&$('rankStage'))loadRanking('rankRows',+$('rankStage').value,true,+$('rankDifficulty').value,$('rankWeapon').value)}catch{}finally{titleRefreshing=false}}
setInterval(refreshLiveTitles,30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLiveTitles()});
